_JSON_PATTERN: Final[re.Pattern[str]] = re.compile(r"```[\s]*(?i:json)[\s]*({[\s\S]+?})[\s]*```", re.DOTALL)

# PATCH
from json_repair import repair_json


class ConverterError(Exception):
    """Error raised when Converter fails to parse the input."""

    def __init__(self, message: str, *args: object) -> None:
        """Initialize the ConverterError with a message.

        Args:
            message: The error message.
            *args: Additional arguments for the base Exception class.
        """
        super().__init__(message, *args)
        self.message = message


class Converter(OutputConverter):
    """Class that converts text into either pydantic or json."""

    def to_pydantic(self, current_attempt: int = 1) -> BaseModel:
        """Convert text to pydantic.

        Args:
            current_attempt: The current attempt number for conversion retries.

        Returns:
            A Pydantic BaseModel instance.

        Raises:
            ConverterError: If conversion fails after maximum attempts.
        """
        try:
            if self.llm.supports_function_calling():
                result = self._create_instructor().to_pydantic()
            else:
                response = self.llm.call(
                    [
                        {"role": "system", "content": self.instructions},
                        {"role": "user", "content": self.text},
                    ]
                )
                try:
                    # Try to directly validate the response JSON
                    result = self.model.model_validate_json(response)
                except ValidationError:
                    # If direct validation fails, attempt to extract valid JSON
                    result = handle_partial_json(
                        result=response,
                        model=self.model,
                        is_json_output=False,
                        agent=None,
                    )
                    # Ensure result is a BaseModel instance
                    if not isinstance(result, BaseModel):
                        if isinstance(result, dict):
                            result = self.model.model_validate(result)
                        elif isinstance(result, str):
                            try:
                                parsed = json.loads(result)
                                result = self.model.model_validate(parsed)
                            except Exception as parse_err:
                                raise ConverterError(
                                    f"Failed to convert partial JSON result into Pydantic: {parse_err}"
                                ) from parse_err
                        else:
                            raise ConverterError(
                                "handle_partial_json returned an unexpected type."
                            ) from None
            return result
        except ValidationError as e:
            print(f"Converter.to_pydantic ValidationError encountered: {current_attempt} attempts. Max: {self.max_attempts}, Error: \n{e}")
            print(f"Converter.to_pydantic ValidationError instructions: \n{self.instructions}")
            print("--"*100)
            print(f"Converter.to_pydantic ValidationError text: \n{self.text}")
            print("--"*100)
            import traceback
            print(traceback.format_exc())
            print("--"*100)
            if current_attempt < self.max_attempts:
                return self.to_pydantic(current_attempt + 1)
            raise ConverterError(
                f"Failed to convert text into a Pydantic model due to validation error: {e}"
            ) from e
        except Exception as e:
            print(f"Converter.to_pydantic Exception encountered: {current_attempt} attempts. Max: {self.max_attempts}, Error: \n{e}")
            print(f"Converter.to_pydantic Exception instructions: \n{self.instructions}")
            print("--"*100)
            print(f"Converter.to_pydantic Exception text: \n{self.text}")
            print("--"*100)
            import traceback
            print(traceback.format_exc())
            print("--"*100)
            if current_attempt < self.max_attempts:
                return self.to_pydantic(current_attempt + 1)
            raise ConverterError(
                f"Failed to convert text into a Pydantic model due to error: {e}"
            ) from e

    def to_json(self, current_attempt: int = 1) -> str | ConverterError | Any:  # type: ignore[override]
        """Convert text to json.

        Args:
            current_attempt: The current attempt number for conversion retries.

        Returns:
            A JSON string or ConverterError if conversion fails.

        Raises:
            ConverterError: If conversion fails after maximum attempts.

        """
        try:
            if self.llm.supports_function_calling():
                return self._create_instructor().to_json()
            return json.dumps(
                self.llm.call(
                    [
                        {"role": "system", "content": self.instructions},
                        {"role": "user", "content": self.text},
                    ]
                )
            )
        except Exception as e:
            if current_attempt < self.max_attempts:
                return self.to_json(current_attempt + 1)
            return ConverterError(f"Failed to convert text into JSON, error: {e}.")

    def _create_instructor(self) -> InternalInstructor:
        """Create an instructor."""

        return InternalInstructor(
            llm=self.llm,
            model=self.model,
            content=self.text,
        )


def convert_to_model(
    result: str,
    output_pydantic: type[BaseModel] | None,
    output_json: type[BaseModel] | None,
    agent: Agent | BaseAgent | None = None,
    converter_cls: type[Converter] | None = None,
) -> dict[str, Any] | BaseModel | str:
    """Convert a result string to a Pydantic model or JSON.

    Args:
        result: The result string to convert.
        output_pydantic: The Pydantic model class to convert to.
        output_json: The Pydantic model class to convert to JSON.
        agent: The agent instance.
        converter_cls: The converter class to use.

    Returns:
        The converted result as a dict, BaseModel, or original string.
    """
    model = output_pydantic or output_json
    if model is None:
        return result
    try:
        escaped_result = json.dumps(json.loads(result, strict=False))
        return validate_model(
            result=escaped_result, model=model, is_json_output=bool(output_json)
        )
    except json.JSONDecodeError:
        return handle_partial_json(
            result=result,
            model=model,
            is_json_output=bool(output_json),
            agent=agent,
            converter_cls=converter_cls,
        )

    except ValidationError:
        return handle_partial_json(
            result=result,
            model=model,
            is_json_output=bool(output_json),
            agent=agent,
            converter_cls=converter_cls,
        )

    except Exception as e:
        Printer().print(
            content=f"Unexpected error during model conversion: {type(e).__name__}: {e}. Returning original result.",
            color="red",
        )
        return result


def validate_model(
    result: str, model: type[BaseModel], is_json_output: bool
) -> dict[str, Any] | BaseModel:
    """Validate and convert a JSON string to a Pydantic model or dict.

    Args:
        result: The JSON string to validate and convert.
        model: The Pydantic model class to convert to.
        is_json_output: Whether to return a dict (True) or Pydantic model (False).

    Returns:
        The converted result as a dict or BaseModel.
    """
    exported_result = model.model_validate_json(result)
    if is_json_output:
        return exported_result.model_dump()
    return exported_result

def save_output_and_validate_error(json_str: str, error:str, model: type[BaseModel]) -> BaseModel:
    import uuid
    import os
    file_id = uuid.uuid4().hex
    os.makedirs("debug", exist_ok=True)
    with open(f"debug/{file_id}.md", "w", encoding="utf-8") as f:
        f.write(f"# MODEL\n{model}\n\n")
        f.write(f"# JSON STRING\n{json_str}\n\n")
        f.write(f"# ERROR\n{error}\n\n")

class CrewValidationError(Exception):
    def __init__(self, error: str, result:str) -> None:
        """Initialize the CrewValidationError with a message.

        Args:
            error: The error message.
            result: The original result string.
        """
        super().__init__(error)
        self.result = result
        self.msg = error

def handle_partial_json(
    result: str,
    model: type[BaseModel],
    is_json_output: bool,
    agent: Agent | BaseAgent | None,
    converter_cls: type[Converter] | None = None,
) -> dict[str, Any] | BaseModel | str:
    """Handle partial JSON in a result string and convert to Pydantic model or dict.

    Args:
        result: The result string to process.
        model: The Pydantic model class to convert to.
        is_json_output: Whether to return a dict (True) or Pydantic model (False).
        agent: The agent instance.
        converter_cls: The converter class to use.

    Returns:
        The converted result as a dict, BaseModel, or original string.
    """
    # print(f"Attempting to handle partial JSON:{result}")
    json_str = result
    match = _JSON_PATTERN.search(result)
    if match:
        json_str = match.group(1)
    # print(f"Extracted JSON string: {json_str}")
    try:
        # PATCH: load for check json validity
        _ = json.loads(json_str)
        exported_result = model.model_validate_json(json_str)
        if is_json_output:
            return exported_result.model_dump()
        return exported_result
    except json.JSONDecodeError as jde:
        print("Handling partial JSON: JSONDecodeError")
        # PATCH: when retry to fix json decode error
        # if agent is None: 
        #     raise jde
        # PATCH: using json_repair to fix common JSON issues
        try:
            print("Attempting JSON repair...")
            repaired_json_str = repair_json(json_str)
            exported_result = model.model_validate_json(repaired_json_str)
            if is_json_output:
                return exported_result.model_dump()
            print(f"JSON repair successful:\n{repaired_json_str}")
            return exported_result
        except ValidationError as ve:
            print(f"Handling partial JSON: ValidationError after repair: \n{ve}")
            # save note to files
            save_output_and_validate_error(repaired_json_str, str(ve), model)
            raise CrewValidationError(str(ve), result=result)
            # raise ve from ve
        except Exception as repair_err:
            print(f"JSON repair failed: {repair_err}")
            raise CrewValidationError(str(repair_err), result=result)
            # raise repair_err from jde
    except ValidationError as ve:
        # PATCH: when retry to fix json ValidationError, avoid throw out no agent error(It's a error info for debug)
        print(f"Handling partial JSON: ValidationError: \n{ve}")
        save_output_and_validate_error(json_str, str(ve), model)
        # save note to files
        raise CrewValidationError(str(ve), result=result)
    except Exception as e:
        Printer().print(
            content=f"Unexpected error during partial JSON handling: {type(e).__name__}: {e}. Attempting alternative conversion method.",
            color="red",
        )
        raise CrewValidationError("Failed to extract, Maybe: 1. Incomplete JSON; 2. No complete ```json``` block.", result=result) # Validation failed (possibly incomplete extract). Forced repair may lose/distort data; raise and let callers return the raw result.
    
    # return convert_with_instructions(
    #     result=result,
    #     model=model,
    #     is_json_output=is_json_output,
    #     agent=agent,
    #     converter_cls=converter_cls,
    # )


def convert_with_instructions(
    result: str,
    model: type[BaseModel],
    is_json_output: bool,
    agent: Agent | BaseAgent | None,
    converter_cls: type[Converter] | None = None,
) -> dict | BaseModel | str:
    """Convert a result string to a Pydantic model or JSON using instructions.

    Args:
        result: The result string to convert.
        model: The Pydantic model class to convert to.
        is_json_output: Whether to return a dict (True) or Pydantic model (False).
        agent: The agent instance.
        converter_cls: The converter class to use.

    Returns:
        The converted result as a dict, BaseModel, or original string.

    Raises:
        TypeError: If neither agent nor converter_cls is provided.

    Notes:
        - TODO: Fix llm typing issues, return llm should not be able to be str or None.
    """
    if agent is None:
        raise TypeError("Agent must be provided if converter_cls is not specified.")

    llm = getattr(agent, "function_calling_llm", None) or agent.llm

    if llm is None:
        raise ValueError("Agent must have a valid LLM instance for conversion")

    instructions = get_conversion_instructions(model=model, llm=llm)
    converter = create_converter(
        agent=agent,
        converter_cls=converter_cls,
        llm=llm,
        text=result,
        model=model,
        instructions=instructions,
    )
    exported_result = (
        converter.to_pydantic() if not is_json_output else converter.to_json()
    )

    if isinstance(exported_result, ConverterError):
        Printer().print(
            content=f"Failed to convert result to model: {exported_result}",
            color="red",
        )
        return result

    return exported_result


def get_conversion_instructions(
    model: type[BaseModel], llm: BaseLLM | LLM | str | Any
) -> str:
    """Generate conversion instructions based on the model and LLM capabilities.

    Args:
        model: A Pydantic model class.
        llm: The language model instance.

    Returns:

    """
    instructions = "Please convert the following text into valid JSON."
    if (
        llm
        and not isinstance(llm, str)
        and hasattr(llm, "supports_function_calling")
        and llm.supports_function_calling()
    ):
        model_schema = PydanticSchemaParser(model=model).get_schema()
        instructions += (
            f"\n\nOutput ONLY the valid JSON and nothing else.\n\n"
            f"The JSON must follow this schema exactly:\n```json\n{model_schema}\n```"
        )
    else:
        model_description = generate_model_description(model)
        instructions += (
            f"\n\nOutput ONLY the valid JSON and nothing else.\n\n"
            f"The JSON must follow this format exactly:\n{model_description}"
        )
    return instructions


class CreateConverterKwargs(TypedDict, total=False):
    """Keyword arguments for creating a converter.

    Attributes:
        llm: The language model instance.
        text: The text to convert.
        model: The Pydantic model class.
        instructions: The conversion instructions.
    """

    llm: BaseLLM | LLM | str
    text: str
    model: type[BaseModel]
    instructions: str


def create_converter(
    agent: Agent | BaseAgent | None = None,
    converter_cls: type[Converter] | None = None,
    *args: Any,
    **kwargs: Unpack[CreateConverterKwargs],
) -> Converter:
    """Create a converter instance based on the agent or provided class.

    Args:
        agent: The agent instance.
        converter_cls: The converter class to instantiate.
        *args: The positional arguments to pass to the converter.
        **kwargs: The keyword arguments to pass to the converter.

    Returns:
        An instance of the specified converter class.

    Raises:
        ValueError: If neither agent nor converter_cls is provided.
        AttributeError: If the agent does not have a 'get_output_converter' method.
        Exception: If no converter instance is created.

    """
    if agent and not converter_cls:
        if hasattr(agent, "get_output_converter"):
            converter = agent.get_output_converter(*args, **kwargs)
        else:
            raise AttributeError("Agent does not have a 'get_output_converter' method")
    elif converter_cls:
        converter = converter_cls(*args, **kwargs)
    else:
        raise ValueError("Either agent or converter_cls must be provided")

    if not converter:
        raise Exception("No output converter found or set.")

    return converter


def generate_model_description(model: type[BaseModel], level: int = 0, parent_field_name: str = "") -> str:
    """Generate a string description of a Pydantic model's fields and their types."""

    def describe_field(field_type: Any, field_name: str = "", field_desc: str = "", current_level: int = 0) -> str:
        """Recursively describe a field's type.
        
        Returns a tuple of (type_description, is_multiline)
        """
        origin = get_origin(field_type)
        args = get_args(field_type)

        if origin is Union or (origin is None and len(args) > 0):
            non_none_args = [arg for arg in args if arg is not type(None)]
            if len(non_none_args) == 1:
                inner_type = non_none_args[0]
                inner_desc = describe_field(inner_type, field_name, field_desc, current_level)
                # Check if inner_type is a BaseModel: prefix with 'Optional' then two spaces
                # so the result becomes: 'Optional  TestObject { ... }'
                if isinstance(inner_type, type) and issubclass(inner_type, BaseModel):
                    return f"Optional  {inner_desc}"
                # Use single-space "Optional " prefix for all other cases
                return f"Optional {inner_desc}"
            return f"Optional[Union[{', '.join(describe_field(arg, field_name, field_desc, current_level) for arg in non_none_args)}]]"
        if origin is list:
            inner_type = args[0]
            # Special handling for List[BaseModel] - expand to multiline
            if isinstance(inner_type, type) and issubclass(inner_type, BaseModel):
                # Generate the nested model at level+2 to get proper indentation (items are 2 levels deeper)
                # Pass field_name to indicate this is an item in the list
                inner_desc = generate_model_description(inner_type, level + 2, parent_field_name=field_name)
                # Need to add indentation to the opening { line
                item_indent = ' ' * ((level + 2) * 2)      # Indentation for items inside List (key + 2 spaces)
                bracket_indent = ' ' * ((level + 1) * 2)    # Indentation for closing ] - same as key indent
                # Split inner_desc into lines
                lines = inner_desc.split('\n')
                # Add indent and class name to the first line (the opening {)
                # e.g. become: '    NameInfo {'
                lines[0] = item_indent + inner_type.__name__ + ' ' + lines[0].lstrip()
                indented_inner = '\n'.join(lines)
                # Format: List[\n    {...}\n  ]  - closing ] aligns with the key name
                # Return without any trailing close-comment
                return f"List[\n{indented_inner}\n{bracket_indent}]"
            return f"List[{describe_field(inner_type, field_name, field_desc, current_level)}]"
        if origin is dict:
            key_type = describe_field(args[0], field_name, field_desc, current_level)
            value_type = describe_field(args[1], field_name, field_desc, current_level)
            return f"Dict[{key_type}, {value_type}]"
        if isinstance(field_type, type) and issubclass(field_type, BaseModel):
            # For nested BaseModel (not inside a List), don't pass parent_field_name
            nested = generate_model_description(field_type, level + 1, parent_field_name="")
            # Prefix the nested block with the actual class name so caller sees: NameInfo { ... }
            return f"{field_type.__name__} {nested}"
        if hasattr(field_type, "__name__"):
            return field_type.__name__
        return str(field_type)

    space_num = (level + 1) * 2
    indent = ' ' * space_num
    
    fields = model.model_fields
    field_descriptions = []
    for i, (name, field) in enumerate(fields.items()):
        field_desc = describe_field(field.annotation, name, field.description, level)
        comma = "," if i < len(fields) - 1 else ""
        desc_text = field.description or ""
        # If the field type description is multiline, attach the comma and the Desc comment to the last line
        if "\n" in field_desc:
            lines = field_desc.split("\n")
            lines[-1] = lines[-1] + comma + (f" // Desc:`{desc_text}`" if desc_text else "")
            field_block = "\n".join(lines)
            field_descriptions.append(f'{indent}"{name}": {field_block}')
        else:
            # Single-line type: append comma and Desc comment on the same line
            desc_comment = (f' // Desc:`{desc_text}`' if desc_text else "")
            field_descriptions.append(f'{indent}"{name}": {field_desc}{comma}{desc_comment}')
    
    # Build result without any trailing close-comments
    result = "{\n" + "\n".join(field_descriptions) + "\n" + ' ' * (level * 2) + "}"
    
    return result
